#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n >= 100) {
        cout << 0 << "\n";
    } else {
        vector<int> a(n + 1), b(n + 1), c(n + 1), d(n + 1), e(n + 1);
        for (int i = 1; i <= n; i++) {
            cin >> a[i] >> b[i] >> c[i] >> d[i] >> e[i];
        }
        unordered_set<int> bad;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (j == i) continue;
                for (int k = 1; k <= n; k++) {
                    if (k == i || k == j) continue;
                    long long ax = a[j] - a[i], bx = b[j] - b[i], cx = c[j] - c[i], dx = d[j] - d[i], ex = e[j] - e[i];
                    long long ay = a[k] - a[i], by = b[k] - b[i], cy = c[k] - c[i], dy = d[k] - d[i], ey = e[k] - e[i];

                    double val = (ax * ay + bx * by + cx * cy + dx * dy + ex * ey);
                    long long m1 = ax * ax + bx * bx + cx * cx + dx * dx + ex * ex;
                    long long m2 = ay * ay + by * by + cy * cy + dy * dy + ey * ey;

                    if (m1 == 0 || m2 == 0) continue; // avoid division by zero
                    val = val / sqrt((double)m1) / sqrt((double)m2);
                    double angle_deg = acos(std::clamp(val, -1.0, 1.0)) * 180.0 / M_PI;
                    if (angle_deg + 1e-9 < 90.0) {
                        bad.insert(i);
                        break; // no need to check further for this i
                    }
                }
                if (bad.count(i)) break; // break outer loop if i is bad
            }
        }
        cout << n - (int)bad.size() << "\n";
        for (int i = 1; i <= n; i++) {
            if (!bad.count(i)) cout << i << "\n";
        }
    }
    return 0;
}
